import csv, math
from datetime import datetime
with open(CATALOG_CSV, 'r') as catalog_csv, open(VALUES_CSV, 'r') as values_csv:
    catalog_reader = csv.DictReader(catalog_csv)
    values_reader = csv.DictReader(values_csv)
    for row_catalog, row_values in zip(catalog_reader, values_reader):
        if row_catalog['point_uri'] == 'https://example.com/Perimeter_bot_ZN_3' and row_catalog['point_class'] == 'weather' and row_catalog['unit'] == '\u00b0C'
            hourly_temperatures = []
            for value in values_reader:
                if value['timeseries_id'] == row_catalog['timeseries_id'] and datetime.strptime(value['timestamp'], '%Y-%m-%d %H:%M:%S') == datetime.strptime('2018-07-07 00:00:00', '%Y-%m-%d %H:%M:%S'):
                    hourly_temperatures.append(float(value['value']))
            if len(hourly_temperatures) == 24:
                print(math.fsum(hourly_temperatures) / len(hourly_temperatures))
